{"ok": true, "result": {"path": "app.js", "text": "import { render } from 'preact';
import { useState, useEffect, useRef, useCallback, useMemo } from 'preact/hooks';
import { html, useCollection, hashRouter, useRoute } from 'spaces-kit';
import { Icon } from './icons.js';
import { fetchForecast, clock } from './weather.js';
import { Today } from './views/today.js';
import { Week } from './views/week.js';
import { Cities } from './views/cities.js';

const space = window.space;

// Forecasts live in memory only (they are fetched, not saved). Last good data is kept on failure.
function useForecasts(cities) {
  const [state, setState] = useState({});
  const seq = useRef({});
  const loaded = useRef({});
  const load = useCallback(async city => {
    const key = `${city.lat},${city.lon}`;
    const n = (seq.current[city.id] = (seq.current[city.id] || 0) + 1);
    loaded.current[city.id] = key;
    setState(s => ({ ...s, [city.id]: { ...s[city.id], key, status: 'loading', data: s[city.id]?.key === key ? s[city.id].data : null } }));
    try {
      const data = await fetchForecast(city);
      if (seq.current[city.id] !== n) return;
      setState(s => ({ ...s, [city.id]: { key, status: 'ok', data, error: null } }));
    } catch (e) {
      if (seq.current[city.id] !== n) return;
      const off = e && e.code === 'not_granted';
      setState(s => ({ ...s, [city.id]: { key, status: off ? 'off' : 'error', data: s[city.id]?.key === key ? s[city.id].data : null, error: off ? 'Internet access is off for this Space.' : (e && e.message) || 'The forecast could not be loaded.' } }));
    }
  }, []);
  const sig = cities.map(c => `${c.id}:${c.lat}:${c.lon}`).join('|');
  useEffect(() => {
    for (const c of cities) if (loaded.current[c.id] !== `${c.lat},${c.lon}`) load(c);
  }, [sig]);
  const reloadAll = useCallback(() => { cities.forEach(load); }, [sig]);
  const reloadOne = useCallback(id => { const c = cities.find(x => x.id === id); if (c) load(c); }, [sig]);
  return { state, reloadAll, reloadOne };
}

const routes = { '/': Today, '/week': Week, '/cities': Cities, '*': Today };
const router = hashRouter(routes);

const NAV = [
  { path: '/', label: 'Today', icon: 'Sun' },
  { path: '/week', label: 'Week', icon: 'CalendarDays' },
  { path: '/cities', label: 'Cities', icon: 'MapPin' }
];

function App() {
  const coll = useCollection('cities', { limit: 200 });
  const route = useRoute();
  const cities = useMemo(() => {
    const list = coll.records.map(r => ({
      id: r.id, rev: r.rev, created: r.created_at,
      name: String(space.field(r, 'name') ?? 'Unnamed'),
      lat: Number(space.field(r, 'lat')), lon: Number(space.field(r, 'lon')),
      favourite: space.field(r, 'favourite') === true, record: r
    })).filter(c => Number.isFinite(c.lat) && Number.isFinite(c.lon));
    list.sort((a, b) => (b.favourite - a.favourite) || (a.created - b.created));
    return list;
  }, [coll.records]);
  const fc = useForecasts(cities);

  const states = cities.map(c => fc.state[c.id]);
  const live = states.filter(s => s?.status === 'ok').length;
  const loading = states.some(s => !s || s.status === 'loading');
  const off = states.some(s => s?.status === 'off');
  const failed = states.filter(s => s?.status === 'error').length;
  const newest = Math.max(0, ...states.map(s => s?.data?.fetchedAt || 0));
  let net;
  if (!cities.length) net = { cls: 'idle', icon: 'Globe', text: 'No cities saved' };
  else if (off) net = { cls: 'bad', icon: 'WifiOff', text: 'Internet access is off for this Space' };
  else if (loading && !newest) net = { cls: 'idle', icon: 'RefreshCw', text: 'Loading forecasts…' };
  else if (failed) net = { cls: 'warn', icon: 'TriangleAlert', text: `${failed} of ${cities.length} forecasts unavailable` };
  else net = { cls: 'ok', icon: 'Check', text: `${live} of ${cities.length} live · retrieved ${newest ? clock(newest) : '–'}` };

  const View = route.component || Today;
  const props = { cities, coll, fc };
  return html`<div class="sky-app">
    <header class="sky-header">
      <div class="sky-brand">
        <span class="sky-mark"><${Icon} name="CloudSun" size=${26} /></span>
        <div><h1>Sky Window</h1><p>Public weather, seven days ahead</p></div>
      </div>
      <nav class="sky-nav" aria-label="Views">
        ${NAV.map(n => html`<a href=${'#' + n.path} aria-current=${route.path === n.path || (n.path === '/' && !route.pattern) ? 'page' : undefined}><${Icon} name=${n.icon} size=${16} /> ${n.label}</a>`)}
      </nav>
      <div class="sky-status">
        <span role="status" class=${'sky-pill sky-pill--' + net.cls}><${Icon} name=${net.icon} size=${14} /> ${net.text}</span>
        <button type="button" class="sky-btn" onClick=${fc.reloadAll} disabled=${!cities.length || loading}><${Icon} name="RefreshCw" size=${14} /> Refresh</button>
      </div>
    </header>
    <main class="sky-main" id="main">
      ${coll.error ? html`<p class="sky-banner sky-banner--bad" role="alert"><${Icon} name="TriangleAlert" size=${16} /> Saved cities could not be read: ${coll.error.message || 'unknown error'}. <button type="button" class="sky-btn" onClick=${coll.reload}>Retry</button></p>` : null}
      ${coll.loading && !coll.records.length ? html`<p class="sky-note" role="status">Loading saved cities…</p>` : null}
      <${View} ...${props} />
    </main>
    <footer class="sky-foot">Forecasts: Open-Meteo.com (public, no key). Temperatures in °C, wind in km/h, precipitation in mm. Cities are public demo places.</footer>
  </div>`;
}

render(html`<${App} />`, document.getElementById('app'));
