const API = 'https://api.open-meteo.com/v1/forecast';

// WMO weather interpretation codes -> label, icon, visual tone.
export function describe(code, isDay = true) {
  const night = !isDay;
  if (code === 0) return night ? { label: 'Clear night', icon: 'Moon', tone: 'night' } : { label: 'Clear sky', icon: 'Sun', tone: 'clear' };
  if (code === 1) return night ? { label: 'Mostly clear night', icon: 'Moon', tone: 'night' } : { label: 'Mostly clear', icon: 'Sun', tone: 'clear' };
  if (code === 2) return { label: 'Partly cloudy', icon: night ? 'CloudMoon' : 'CloudSun', tone: night ? 'night' : 'cloud' };
  if (code === 3) return { label: 'Overcast', icon: 'Cloud', tone: 'cloud' };
  if (code === 45 || code === 48) return { label: 'Fog', icon: 'CloudFog', tone: 'fog' };
  if (code >= 51 && code <= 57) return { label: 'Drizzle', icon: 'CloudDrizzle', tone: 'rain' };
  if (code >= 61 && code <= 67) return { label: 'Rain', icon: 'CloudRain', tone: 'rain' };
  if (code >= 71 && code <= 77) return { label: 'Snow', icon: 'CloudSnow', tone: 'snow' };
  if (code >= 80 && code <= 82) return { label: 'Rain showers', icon: 'CloudRain', tone: 'rain' };
  if (code === 85 || code === 86) return { label: 'Snow showers', icon: 'CloudSnow', tone: 'snow' };
  if (code >= 95) return { label: 'Thunderstorm', icon: 'CloudLightning', tone: 'storm' };
  return { label: 'Unknown conditions', icon: 'Cloud', tone: 'cloud' };
}

const num = v => (typeof v === 'number' && Number.isFinite(v) ? v : null);

// space.net.fetch(url, {as: 'json'}) resolves to {status, url, headers, json}.
// The parsed payload is res.json (a property, not a method; there is no .body).
function unwrap(res) {
  if (!res || typeof res !== 'object' || typeof res.status !== 'number') {
    const e = new Error('The network bridge returned an unexpected response.');
    e.code = 'shape';
    throw e;
  }
  if (res.status < 200 || res.status >= 300) {
    const reason = res.json && typeof res.json === 'object' && res.json.reason ? ` ${res.json.reason}` : '';
    const e = new Error(`Open-Meteo answered with status ${res.status}.${reason}`);
    e.code = 'http';
    throw e;
  }
  return res.json;
}

export async function fetchForecast(city) {
  const url = new URL(API);
  const params = {
    latitude: city.lat, longitude: city.lon,
    current: 'temperature_2m,apparent_temperature,relative_humidity_2m,weather_code,wind_speed_10m,is_day,precipitation',
    daily: 'weather_code,temperature_2m_max,temperature_2m_min,precipitation_sum,precipitation_probability_max',
    forecast_days: 7, timezone: 'auto', temperature_unit: 'celsius', wind_speed_unit: 'kmh', precipitation_unit: 'mm'
  };
  for (const [k, v] of Object.entries(params)) url.searchParams.set(k, String(v));
  const raw = unwrap(await space.net.fetch(url.toString(), { as: 'json' }));
  const data = typeof raw === 'string' ? JSON.parse(raw) : raw;
  if (data?.error) { const e = new Error(data.reason || 'Open-Meteo rejected the request.'); e.code = 'http'; throw e; }
  const c = data?.current, d = data?.daily;
  if (!c || num(c.temperature_2m) === null || !d || !Array.isArray(d.time) || d.time.length < 1) {
    const e = new Error('Open-Meteo returned an incomplete forecast.');
    e.code = 'shape';
    throw e;
  }
  const days = d.time.map((date, i) => ({
    date, code: num(d.weather_code?.[i]), hi: num(d.temperature_2m_max?.[i]), lo: num(d.temperature_2m_min?.[i]),
    rain: num(d.precipitation_sum?.[i]), prob: num(d.precipitation_probability_max?.[i])
  })).filter(x => x.hi !== null && x.lo !== null);
  if (!days.length) { const e = new Error('Open-Meteo returned no daily values.'); e.code = 'shape'; throw e; }
  return {
    fetchedAt: Date.now(),
    tz: data.timezone_abbreviation || data.timezone || '',
    current: {
      time: c.time, temp: c.temperature_2m, feels: num(c.apparent_temperature), humidity: num(c.relative_humidity_2m),
      wind: num(c.wind_speed_10m), code: num(c.weather_code) ?? -1, isDay: c.is_day !== 0, precip: num(c.precipitation)
    },
    days
  };
}

export const deg = v => (v === null || v === undefined ? '–' : `${Math.round(v)}°`);
export const clock = ms => new Date(ms).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
export const weekday = (date, opts = { weekday: 'short' }) => new Date(date + 'T12:00:00').toLocaleDateString([], opts);
