{"ok": true, "result": {"path": "views/cities.js", "text": "import { useState, useRef } from 'preact/hooks';
import { html, useSaveState, SaveIndicator, ConflictBanner, EmptyState } from 'spaces-kit';
import { Icon } from '../icons.js';

const space = window.space;

export function Cities({ cities, coll }) {
  const save = useSaveState();
  const [name, setName] = useState('');
  const [lat, setLat] = useState('');
  const [lon, setLon] = useState('');
  const [error, setError] = useState('');
  const [confirm, setConfirm] = useState(null);
  const [retry, setRetry] = useState(null);
  const busy = useRef(false);
  const saving = save.state === 'saving';

  const guarded = async (fn, again) => {
    if (busy.current) return;
    busy.current = true;
    setRetry(() => again || fn);
    try { return await save.run(fn); } finally { busy.current = false; }
  };

  const add = async () => {
    if (saving) return;
    const n = name.trim(), la = Number(lat), lo = Number(lon);
    if (!n) return setError('Enter a city name.');
    if (n.length > 80) return setError('Keep the name under 80 characters.');
    if (lat.trim() === '' || !Number.isFinite(la) || la < -90 || la > 90) return setError('Latitude must be a number from -90 to 90.');
    if (lon.trim() === '' || !Number.isFinite(lo) || lo < -180 || lo > 180) return setError('Longitude must be a number from -180 to 180.');
    if (cities.some(c => c.name.toLowerCase() === n.toLowerCase())) return setError(`${n} is already saved.`);
    setError('');
    const created = await guarded(async () => {
      const r = await space.put('cities', null, { name: n, lat: la, lon: lo, favourite: false }, { baseRev: 0 });
      setName(''); setLat(''); setLon('');
      coll.reload();
      return r;
    });
    return created;
  };
  const onEnter = e => {
    if (e.key !== 'Enter' || e.isComposing || e.keyCode === 229 || e.repeat || e.altKey || e.ctrlKey || e.metaKey || e.shiftKey) return;
    e.preventDefault();
    add();
  };

  // Exactly one favourite: clear any others and set this one in a single all-or-nothing batch.
  const setFavourite = id => async () => {
    if (saving) return;
    const run = async () => {
      const fresh = await space.query('cities', { limit: 200 });
      const target = fresh.find(r => r.id === id);
      if (!target) throw new Error('That city no longer exists.');
      const makeFav = target.data.favourite !== true;
      const ops = [];
      for (const r of fresh) {
        const want = makeFav && r.id === id;
        if ((r.data.favourite === true) !== want) ops.push({ op: 'put', collection: 'cities', id: r.id, data: { ...r.data, favourite: want }, base_rev: r.rev });
      }
      if (ops.length) await space.batch(ops);
      coll.reload();
    };
    await guarded(run);
  };

  const remove = id => async () => {
    if (saving) return;
    const run = async () => {
      const cur = await space.get('cities', id);
      await space.delete('cities', id, { baseRev: cur.rev });
      setConfirm(null);
      coll.reload();
    };
    await guarded(run);
  };

  const fav = cities.find(c => c.favourite);
  return html`<section aria-labelledby="cities-h">
    <div class="sky-viewhead"><h2 id="cities-h">Cities</h2><p>${cities.length} saved · ${fav ? `Favourite: ${fav.name}` : 'No favourite yet'}. Changes are saved as soon as you confirm them.</p></div>
    <div class="sky-split">
      <div role="group" aria-label="Add a city" class="sky-add">
        <h3><${Icon} name="Plus" size=${16} /> Add a city</h3>
        <label>City name<input type="text" value=${name} maxlength="80" placeholder="Reykjavik" disabled=${saving} onInput=${e => setName(e.target.value)} onKeyDown=${onEnter} /></label>
        <div class="sky-pair">
          <label>Latitude<input type="text" inputmode="decimal" value=${lat} placeholder="64.1466" disabled=${saving} onInput=${e => setLat(e.target.value)} onKeyDown=${onEnter} /></label>
          <label>Longitude<input type="text" inputmode="decimal" value=${lon} placeholder="-21.9426" disabled=${saving} onInput=${e => setLon(e.target.value)} onKeyDown=${onEnter} /></label>
        </div>
        <p class="sky-hint">Decimal degrees. South and west are negative.</p>
        ${error ? html`<p class="sky-error" role="alert"><${Icon} name="TriangleAlert" size=${14} /> ${error}</p>` : null}
        <button type="button" class="sky-btn sky-btn--primary" onClick=${add} disabled=${saving || !name.trim()}><${Icon} name="Plus" size=${14} /> Add city</button>
      </div>
      <div>
        <div class="sky-savebar"><${SaveIndicator} state=${save.state} message=${save.state === 'idle' ? 'Nothing pending' : save.message} /></div>
        ${save.state === 'conflict' ? html`<${ConflictBanner} current=${save.current} message="A city changed elsewhere while you were editing." onKeepMine=${() => retry && guarded(retry)} onUseUpdated=${() => save.run(async () => { await coll.reload(); })} />` : null}
        ${!cities.length && !coll.loading ? html`<${EmptyState} title="No cities saved"><p>Add one with the form to get started.</p><//>` : html`<ul class="sky-citylist">
          ${cities.map(c => html`<li key=${c.id} class=${'sky-cityrow' + (c.favourite ? ' is-fav' : '')}>
            <div class="sky-cityname"><strong>${c.name}</strong><span>${c.lat.toFixed(4)}°, ${c.lon.toFixed(4)}°${c.favourite ? ' · Favourite' : ''}</span></div>
            <div class="sky-rowact">
              <button type="button" class="sky-btn" aria-pressed=${String(c.favourite)} disabled=${saving} onClick=${setFavourite(c.id)} aria-label=${c.favourite ? `Unmark ${c.name} as favourite` : `Make ${c.name} my favourite`}><${Icon} name="Star" size=${14} fill=${c.favourite} /> ${c.favourite ? 'Favourite' : 'Make favourite'}</button>
              ${confirm === c.id ? html`<button type="button" class="sky-btn sky-btn--danger" disabled=${saving} onClick=${remove(c.id)}><${Icon} name="Trash2" size=${14} /> Confirm remove</button><button type="button" class="sky-btn" onClick=${() => setConfirm(null)}>Cancel</button>`
                : html`<button type="button" class="sky-btn" disabled=${saving} onClick=${() => setConfirm(c.id)} aria-label=${`Remove ${c.name}`}><${Icon} name="Trash2" size=${14} /> Remove</button>`}
            </div>
          </li>`)}
        </ul>`}
      </div>
    </div>
  </section>`;
}
