{"ok": true, "result": {"path": "views/panel.js", "text": "import { html } from 'spaces-kit';
import { Icon } from '../icons.js';
import { describe, deg, clock } from '../weather.js';

// Shared "unavailable" explanation for one city, used by Today and Week.
export function Unavailable({ status, error, onRetry, name }) {
  const off = status === 'off';
  return html`<div class=${'sky-unavail' + (off ? ' sky-unavail--off' : '')} role="status">
    <${Icon} name=${off ? 'WifiOff' : 'TriangleAlert'} size=${22} />
    <div>
      <strong>${off ? 'Internet access is off for this Space' : `${name} forecast unavailable`}</strong>
      <p>${off ? 'Turn Internet access on in this Space\'s Permissions to load live forecasts. Your saved cities still work.' : `${error || 'The forecast service did not answer.'} Your saved cities are unaffected.`}</p>
      ${onRetry ? html`<button type="button" class="sky-btn" onClick=${onRetry}><${Icon} name="RefreshCw" size=${14} /> Try again</button>` : null}
    </div>
  </div>`;
}

export function CityPanel({ city, entry, onRetry }) {
  const data = entry?.data;
  const cur = data?.current;
  const info = cur ? describe(cur.code, cur.isDay) : null;
  const today = data?.days?.[0];
  const stale = data && (entry.status === 'error' || entry.status === 'off');
  return html`<article class=${'sky-panel' + (city.favourite ? ' sky-panel--fav' : '')} data-tone=${info ? info.tone : 'none'} aria-labelledby=${'t-' + city.id}>
    <header class="sky-panel-head">
      <h2 id=${'t-' + city.id}>${city.name}</h2>
      ${city.favourite ? html`<span class="sky-fav"><${Icon} name="Star" size=${14} fill=${true} /> Favourite</span>` : null}
      <span class="sky-coords">${city.lat.toFixed(2)}°, ${city.lon.toFixed(2)}°</span>
    </header>
    ${cur ? html`<div class="sky-now">
      <div class="sky-temp"><span class="sky-temp-num">${Math.round(cur.temp)}</span><span class="sky-temp-unit">°C</span></div>
      <div class="sky-cond"><${Icon} name=${info.icon} size=${44} /><span>${info.label}</span></div>
      <dl class="sky-stats">
        <div><dt><${Icon} name="Thermometer" size=${14} /> Feels like</dt><dd>${deg(cur.feels)}</dd></div>
        <div><dt><${Icon} name="Droplets" size=${14} /> Humidity</dt><dd>${cur.humidity === null ? '–' : Math.round(cur.humidity) + '%'}</dd></div>
        <div><dt><${Icon} name="Wind" size=${14} /> Wind</dt><dd>${cur.wind === null ? '–' : Math.round(cur.wind) + ' km/h'}</dd></div>
        <div><dt><${Icon} name="Umbrella" size=${14} /> Rain today</dt><dd>${today && today.rain !== null ? today.rain.toFixed(1) + ' mm' : '–'}</dd></div>
        <div><dt>High today</dt><dd>${today ? deg(today.hi) : '–'}</dd></div>
        <div><dt>Low today</dt><dd>${today ? deg(today.lo) : '–'}</dd></div>
      </dl>
      <p class="sky-asof">Local time at forecast ${String(cur.time).slice(11, 16)} ${data.tz} · retrieved ${clock(data.fetchedAt)}${stale ? ' · last good data, update failed' : ''}</p>
    </div>` : null}
    ${!cur && (!entry || entry.status === 'loading') ? html`<p class="sky-loading" role="status">Loading ${city.name} from Open-Meteo…</p>` : null}
    ${(!cur && entry && (entry.status === 'error' || entry.status === 'off')) || stale ? html`<${Unavailable} status=${entry.status} error=${entry.error} name=${city.name} onRetry=${onRetry} />` : null}
  </article>`;
}
