import { html, EmptyState } from 'spaces-kit';
import { createChart, LineSeries, HistogramSeries, ColorType, CrosshairMode } from 'lightweight-charts';
import { Icon } from '../icons.js';
import { describe, deg, weekday } from '../weather.js';
import { Unavailable } from './panel.js';

// Resolve a CSS custom property (possibly a light-dark() value) to a concrete rgb colour.
function resolve(el, name) {
  const probe = document.createElement('span');
  probe.style.color = `var(${name})`;
  probe.style.display = 'none';
  el.appendChild(probe);
  const c = getComputedStyle(probe).color;
  probe.remove();
  return c;
}

function WeekChart({ days, name, scheme }) {
  const host = useRef(null);
  const [hover, setHover] = useState(null);
  useEffect(() => {
    const el = host.current;
    if (!el) return;
    const ink = resolve(el, '--sky-ink'), muted = resolve(el, '--sky-muted'), line = resolve(el, '--sky-line');
    const hot = resolve(el, '--sky-hot'), cool = resolve(el, '--sky-cool'), rain = resolve(el, '--sky-rain');
    const chart = createChart(el, {
      autoSize: true,
      layout: { background: { type: ColorType.Solid, color: 'rgba(0,0,0,0)' }, textColor: muted, fontSize: 12, attributionLogo: false },
      grid: { vertLines: { visible: false }, horzLines: { color: line } },
      rightPriceScale: { borderVisible: false, scaleMargins: { top: 0.14, bottom: 0.3 } },
      timeScale: { borderVisible: false, fixLeftEdge: true, fixRightEdge: true, tickMarkFormatter: t => typeof t === 'string' ? weekday(t) : weekday(`${t.year}-${String(t.month).padStart(2, '0')}-${String(t.day).padStart(2, '0')}`) },
      crosshair: { mode: CrosshairMode.Magnet, vertLine: { color: ink, labelVisible: false }, horzLine: { visible: false, labelVisible: false } },
      handleScroll: false, handleScale: false
    });
    const fmt = u => ({ type: 'custom', formatter: v => v.toFixed(u === 'mm' ? 1 : 0) + (u === 'mm' ? ' mm' : '°') , minMove: 0.1 });
    const hi = chart.addSeries(LineSeries, { color: hot, lineWidth: 3, title: 'High °C', priceFormat: fmt('c'), pointMarkersVisible: true, pointMarkersRadius: 4 });
    const lo = chart.addSeries(LineSeries, { color: cool, lineWidth: 3, title: 'Low °C', priceFormat: fmt('c'), pointMarkersVisible: true, pointMarkersRadius: 4 });
