.sky-stats dd { margin: 2px 0 0; font-family: var(--space-mono); font-size: 18px; font-weight: 600; }
.sky-asof { grid-column: 1 / -1; margin: 10px 0 0; font-size: 12px; color: var(--sky-muted); }
@media (max-width: 560px) { .sky-now { grid-template-columns: 1fr; } .sky-header { grid-template-columns: 1fr; } .sky-status { justify-content: flex-start; } }

.sky-unavail { display: flex; gap: 12px; margin-top: 14px; padding: 12px 14px; border-radius: var(--space-radius); border: 1px dashed light-dark(#b7791f, #e0b04a); background: var(--space-surface); }
.sky-unavail--off { border-color: light-dark(#b42318, #ff8a80); }
.sky-unavail p { margin: 4px 0 8px; font-size: 13px; color: var(--sky-muted); }

/* Week */
.sky-tabs { display: flex; gap: 8px; flex-wrap: wrap; margin-bottom: 14px; }
.sky-tab { display: inline-flex; gap: 6px; align-items: center; padding: 7px 16px; border-radius: 999px; border: 1px solid var(--space-control-line); background: transparent; color: var(--sky-ink); font: inherit; font-weight: 600; cursor: pointer; }
.sky-tab[aria-pressed="true"] { background: var(--sky-ink); color: var(--space-bg); border-color: var(--sky-ink); }
.sky-weekcard { padding: 18px 20px; border-radius: var(--space-radius-lg); background: var(--space-card); border: 1px solid var(--sky-line); }
.sky-chart { height: 340px; width: 100%; }
.sky-readout { display: flex; flex-wrap: wrap; gap: 6px 18px; align-items: baseline; margin: 0 0 8px; font-size: 14px; min-height: 22px; }
.sky-readout .k { font-family: var(--space-mono); font-weight: 600; }
.k-hot { color: var(--sky-hot); } .k-cool { color: var(--sky-cool); } .k-rain { color: var(--sky-rain); }
.sky-hint { color: var(--sky-muted); font-size: 12px; margin: 0; }
.sky-legend { display: flex; gap: 18px; flex-wrap: wrap; list-style: none; padding: 0; margin: 8px 0 0; font-size: 12px; color: var(--sky-muted); }
.sw { display: inline-block; width: 18px; height: 4px; border-radius: 2px; vertical-align: middle; margin-right: 4px; }
.sw-hot { background: var(--sky-hot); } .sw-cool { background: var(--sky-cool); } .sw-rain { background: var(--sky-rain); height: 10px; }
.sky-table-wrap { overflow-x: auto; margin-top: 18px; }
.sky-table { width: 100%; border-collapse: collapse; font-size: 14px; }
.sky-table caption { text-align: left; font-size: 12px; color: var(--sky-muted); padding-bottom: 6px; }
.sky-table th, .sky-table td { text-align: left; padding: 8px 10px; border-top: 1px solid var(--sky-line); white-space: nowrap; }
.sky-table thead th { font-size: 11px; text-transform: uppercase; letter-spacing: .08em; color: var(--sky-muted); border-top: 0; }
.sky-table td { font-family: var(--space-mono); }
.sky-table td:nth-child(2) { font-family: inherit; }

/* Cities */
.sky-split { display: grid; grid-template-columns: minmax(260px, 340px) 1fr; gap: 28px; align-items: start; }
@media (max-width: 760px) { .sky-split { grid-template-columns: 1fr; } }
.sky-add { display: grid; gap: 12px; padding: 18px; border-radius: var(--space-radius-lg); background: var(--space-card); border: 1px solid var(--sky-line); }
.sky-add h3 { margin: 0; font-size: 15px; display: flex; gap: 6px; align-items: center; }
.sky-add label { display: grid; gap: 4px; font-size: 12px; font-weight: 700; color: var(--sky-muted); text-transform: uppercase; letter-spacing: .06em; }
.sky-add input { padding: 9px 10px; font: inherit; font-size: 15px; text-transform: none; letter-spacing: 0; font-weight: 400; color: var(--sky-ink); background: var(--space-bg); border: 1px solid var(--space-control-line); border-radius: var(--space-radius); min-width: 0; }
.sky-pair { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
